head.script:
scwin.onpageload = function() {
	var _param = $p.getParameter("exam_param") || {};
    tbx_type.setValue(_param.type);
};

/**
 * @method  $p
 * @name    isPopup
 * @cdate   2014-03-11
 * @version 5.0 
 * @author  전병진
 * @description
 *  현재 Window(화면)가 popup인지의 여부를 반환합니다.
 * @param   <Boolean:N> closest   중첩된 wframe 팝업 또는 browser 팝업안에 wframe이 있을 경우, 부모 frame의 팝업 여부 체크.
 * @see 
 * @return  <boolean> 팝업인 경우 true, 팝업이 아닌 경우 false 
 * @exception   
 * @sample
 * |var ispopup = $p.isPopup();
 * |//return 예시 ) false
 * |중첩된 wframe 팝업 또는 browser 팝업안에 wframe이 있을 경우, 팝업 여부를 자식 wframe에서 확인할 경우
 * |var ispopup = $p.isPopup(true);
 * @hidden false
 * @deprecated
 */
scwin.sample_org = function () {

};

scwin.sample = function () {

};

scwin.btn_exam1_onclick = function (e) {
    alert($p.isPopup());
};

scwin.btn_exam2_onclick = function (e) {
    alert($p.isPopup(true));
};
